  add('beginner','right_corner',n,'直角を見つける','紙のかどとぴったり重なる、直角のかどはどれ？',['A','B','C'][n],
   f'{["A","B","C"][n]}のかどに紙のかどを重ねると、すき間なく重なります。三角形の向きがかわっても直角です。','紙のかどを重ねると、すき間なく重なるから',dict(right=n),choices=['A','B','C'],action='紙のかどを重ねる')
  lengths=[[4,4,3],[4,4,4],[3,4,5]][n];name=['二等辺三角形（2辺だけ同じ）','正三角形','どちらでもない'][n]
  add('beginner','equal_sides',n,'同じ長さの辺','辺の長さを見て、この三角形の名前をえらぼう。',name,
   ['2つの辺が同じ長さなので、二等辺三角形です。','3つの辺がすべて同じ長さなので、正三角形です。','3つの辺の長さがどれも違うので、どちらでもありません。'][n],
   ['2つの辺が同じ長さだから','3つの辺がすべて同じ長さだから','3つの辺の長さがどれも違うから'][n],dict(lengths=lengths),choices=['二等辺三角形（2辺だけ同じ）','正三角形','どちらでもない'],action='同じ長さの辺を色で見る',wrong_reasons=['向きが上を向いているから','一番長い辺だけで決まるから'])
  r=n+2
  add('beginner','diameter',n,'半径と直径',f'円の半径は{r}cm。中心を通る、はしからはしまでの長さは？',2*r,
   f'中心から円のはしまでが半径。直径は半径2本分なので、{r}＋{r}＝{2*r}cmです。','中心を通る長さは、半径2本分だから',dict(r=r),unit='cm',ui='line',action='中心を通る線を引く')
  b,h=3+n,2+n
