  add('intermediate','parallelogram',n,'切って移す',f'底辺{b}cm、高さ{h}cmの平行四辺形。面積は？',b*h,
   f'左の三角形を右へ移すと、横{b}cm・縦{h}cmの長方形。面積は{b*h}cm²です。','重ならず、すき間もなく移しただけなので、面積が同じだから',dict(b=b,h=h),visual='parallelogram',ui='motion',control='切った三角形を右へ移す',unit='cm²')
  a=b//2
