BY_ID = {q["id"]:q for q in LEGACY_BANK+BANK}


def setting(name):
    value=os.environ.get(name,'')
    if value:return value
    try:return str(st.secrets.get(name,''))
    except (FileNotFoundError,st.errors.StreamlitSecretNotFoundError):return ''


def cloud_config():
    url=setting('SUPABASE_URL').rstrip('/')
    key=setting('SUPABASE_SECRET_KEY') or setting('SUPABASE_SERVICE_ROLE_KEY')
    if not url or not key:return None
    if not url.startswith('https://'):raise ValueError('SUPABASE_URL は https:// で設定してください。')
    # Secret key is server-only; an anon/publishable key cannot use this schema.
    if key.startswith('sb_publishable_'):raise ValueError('サーバー用の SUPABASE_SECRET_KEY または SERVICE_ROLE_KEY が必要です。')
    headers={'apikey':key,'Content-Type':'application/json'}
    if not key.startswith('sb_secret_'):headers['Authorization']='Bearer '+key
    return url+'/rest/v1/'+TABLE,headers


def valid_uuid(value):
    return str(UUID(str(value)))


def validate_rows(rows,device):
    if not isinstance(rows,list) or len(rows)>25:raise ValueError('送信件数が不正です。')
    clean=[]
    for row in rows:
        q=BY_ID.get(row.get('question_id'))
        answer=row.get('answer');seconds=row.get('seconds',0)
        if not q or type(answer) is not int or not 0<=answer<len(q['choices']):raise ValueError('回答が不正です。')
        if row.get('mode') not in ['learn','challenge','review']:raise ValueError('モードが不正です。')
        if type(seconds) not in [int,float] or not math.isfinite(seconds) or not 0<=seconds<=86400:raise ValueError('時間が不正です。')
        if type(row.get('hint_used')) is not bool:raise ValueError('ヒント情報が不正です。')
        if q.get('course') and row.get('reason_answer') is not None and (type(row.get('reason_answer')) is not int or not 0<=row['reason_answer']<len(q['reason_choices'])):raise ValueError('考え方の回答が不正です。')
        created=datetime.fromisoformat(str(row['client_created']).replace('Z','+00:00'))
        if created.tzinfo is None:raise ValueError('日時にはタイムゾーンが必要です。')
        clean.append(dict(id=valid_uuid(row['id']),device_id=device,question_id=q['id'],mode=row['mode'],answer=answer,correct=answer==q['answer'] and (not q.get('course') or row.get('reason_answer') is None or row.get('reason_answer')==q['reason_answer']),hint_used=row['hint_used'],seconds=int(seconds),client_created=created.astimezone(timezone.utc).isoformat()))
    return clean


def play_instruction(q):
    visual=q.get('visual');family=q.get('family')
    if visual=='butterfly':return '点Oを指で上下左右にドラッグできる。Oに合わせて上底ABが動く。ABとCDは平行、ABとCDの長さは変えられない。A/B/C/Dを個別に動かす操作はない。'
    if visual=='trapezoid_cross':return '点Oを左右だけにドラッグできる。上底ABが左右に動く。上下の底辺の長さ・平行・高さは固定。Oを上下に動かす操作はない。'
    if visual in ('area_ratio','cevians'):return '点Aを左右だけにドラッグできる。底辺BCと高さは固定。D/E/Pは条件に合わせて連動する。D/E/Pを個別に動かす操作はない。'
    if visual=='diameter':return '円周上の①②の点をそれぞれドラッグして半径の向きを回せる。中心は固定。'
    if visual=='box':return '立体をドラッグして見る向きを回せる。積み木の個数や辺の長さは変えられない。'
    if family in ('fold_match','equal_sides','compose','perimeter','sides','right_corner'):return {'fold_match':'折り線A/B/Cを選び、折る量をスライダーまたは指で変えられる。','equal_sides':'三辺を取り出してそろえる量をスライダーまたは指で変えられる。','compose':'対角線を選んで切り、三角形を指やスライダーで回して重ねられる。','perimeter':'周りの点を指で動かして一周たどれる。','sides':'辺をタップして数え、図形を回せる。','right_corner':'紙の角をドラッグして動かし、回して重ねられる。'}[family]
    if q.get('ui')=='motion':return '図形をドラッグ、またはスライダーで「'+str(q.get('control','位置'))+'」を変えられる。指定されていない頂点の個別移動はできない。'
    return '図形全体を指でドラッグまたは回転スライダーで回せる。各点の位置関係・長さ・角度は固定。頂点や交点を個別に動かす操作はない。'


def thinking_assist(event,session,request=requests.request):
    q=BY_ID.get(event.get('question_id'))
    step=event.get('step');token=valid_uuid(event.get('token'))
    if not q or type(step) is not int or not 1<=step<=max(1,len(q.get('hints',[]))):
        raise ValueError('ヒントの指定が不正です。')
    hints=q.get('hints') or [q.get('reason_choices',['図の辺や角を比べてみよう。'])[q.get('reason_answer',0)]]
    reference=hints[min(step-1,len(hints)-1)]
    cache=session.setdefault('assist_cache',{})
    cache_key='play10:'+q['id']+':'+str(step)
    if cache_key in cache:return dict(cache[cache_key],token=token)
    result={'question_id':q['id'],'step':step,'token':token,'provider':'reference','text':reference}
    key=setting('OPENAI_API_KEY')
    if key:
        try:
            result['provider']='unavailable'
            calls=session.setdefault('assist_calls',[]);now=datetime.now(timezone.utc).timestamp()
            calls[:]=[v for v in calls if now-v<3600]
            if len(calls)>=30:raise ValueError('AI利用の上限です。')
            calls.append(now)
            payload={'model':setting('OPENAI_MODEL') or 'gpt-4.1-mini','store':False,'max_output_tokens':500,
                'instructions':'あなたは子どもの図形学習を助ける先生です。答えや最後の計算結果を先に教えず、今回のヒントを短い日本語2〜3文で言い換えてください。図の点名・色・番号を使い、注目する場所と次に試せる操作を一つ示し、問いかけで終えます。図にない色や線は作らないでください。操作欄に書かれた操作だけを案内し、固定された点を動かすなど存在しない操作は絶対に勧めないでください。',
                'input':json.dumps({'問題':q['prompt'],'段階':step,'今回のヒント':reference,'図の表示':('①ABPは黄色。段階1は②ACPが橙色、ADを黄色で強調。段階2は②BCPが橙色、BEを黄色で強調。段階3は②BCPが橙色、③CAPが青色。' if q.get('visual')=='cevians' else '補助線は薄い黄色で強調。'),'操作':play_instruction(q)},ensure_ascii=False)}
            response=request('POST','https://api.openai.com/v1/responses',headers={'Authorization':'Bearer '+key,'Content-Type':'application/json'},json=payload,timeout=(4,20))
            response.raise_for_status();data=response.json()
            text='\n'.join(c.get('text','') for item in data.get('output',[]) if item.get('type')=='message' for c in item.get('content',[]) if c.get('type')=='output_text').strip()
            if not text:raise ValueError('AIの回答が空です。')
            result.update(provider='ai',text=text[:1600])
        except (requests.RequestException,ValueError,TypeError,KeyError):pass
    cache[cache_key]={k:v for k,v in result.items() if k!='token'}
    return result


def process_event(event,session,config,request=requests.request):
    request_id=valid_uuid(event.get('request_id'))
    device=valid_uuid(event.get('device_id'))
    if session.get('device') and session['device']!=device:raise ValueError('端末IDが一致しません。ページを再読み込みしてください。')
    session['device']=device
    response={'request_id':request_id,'configured':bool(config),'ok':False,'message':'この端末に保存（Supabase未設定）'}
    if event.get('type')=='assist':
        response.update(ok=True,assist=thinking_assist(event,session,request));return response
    if event.get('type') not in ['load','save']:raise ValueError('操作が不正です。')
    if not config:return response
    url,headers=config
    try:
        if event['type']=='load':
            # The full random device UUID is the possession capability. No device listing API.
            result=request('GET',url,headers=headers,params={'device_id':'eq.'+device,'select':'id,question_id,mode,answer,correct,hint_used,seconds,client_created','order':'client_created.desc,id.desc','limit':'1000'},timeout=(4,12))
            result.raise_for_status();response['rows']=list(reversed(result.json()))
        else:
            rows=validate_rows(event.get('rows'),device)
            if rows:
                result=request('POST',url,headers={**headers,'Prefer':'resolution=ignore-duplicates,return=minimal'},params={'on_conflict':'id'},json=rows,timeout=(4,12));result.raise_for_status()
            response['ack']=[r['id'] for r in rows]
        response.update(ok=True,message='Supabaseと同期済み')
    except requests.RequestException as exc:
        status=getattr(getattr(exc,'response',None),'status_code',None)
        response['message']='端末に保存済み · 同期できません'+(f'（HTTP {status}）' if status else '')
    return response


@st.cache_resource
def get_component(frontend):
    digest=hashlib.sha256(frontend.encode()).hexdigest()[:16]
    path=Path(tempfile.gettempdir())/('geometry_atelier_'+digest)
    path.mkdir(parents=True,exist_ok=True)
    (path/'index.html').write_text(frontend,encoding='utf-8')
    return components.declare_component('geometry_atelier_v1_'+digest,path=str(path))


def main():
    st.set_page_config(page_title='chokomana_ずけいのアトリエ',page_icon='🔷',layout='centered')
    st.markdown('<style>.block-container{padding-top:1rem;padding-bottom:0;max-width:820px}header[data-testid="stHeader"]{background:transparent}[data-testid="stMainBlockContainer"]{padding-left:.4rem;padding-right:.4rem}</style>',unsafe_allow_html=True)
    try:config=cloud_config()
    except ValueError as exc:st.error(str(exc));config=None
    state=st.session_state.setdefault('geometry_state',{})
    state.setdefault('response',{'configured':bool(config),'message':'記録を準備しています…'})
    event=get_component(FRONTEND)(bank=BANK,topics=TOPICS,levels=LEVELS,response=state['response'],key='geometry_atelier',default=None)
    if isinstance(event,dict) and event.get('request_id')!=state.get('last_request'):
        state['last_request']=event.get('request_id')
        try:
            previous_message=state['response'].get('message')
            state['response']=process_event(event,state,config)
            if event.get('type')=='assist' and previous_message:state['response']['message']=previous_message
        except (ValueError,TypeError,KeyError,AttributeError) as exc:
            state['response']={'request_id':event.get('request_id'),'configured':bool(config),'ok':False,'message':'同期する記録を確認できません。再読み込みしてください。'}
        st.rerun()


if __name__=='__main__':main()
